import {offerStreetFinisher,startStreetFinisher,stepStreetFinisher} from './street-finishers.js';
import {createMotion,stepMotion,addInjury,approach,stepVertical} from './physics.js';
import {difficulty} from './preferences.js';
// Side-scrolling campaign. World x, ground lane and jump height are independent.
export const clamp=(v,a,b)=>Math.max(a,Math.min(v,b));
export {stages} from './campaign.js';
import {stages,bossFor,campaignSides} from './campaign.js';
export const arenaMissions={stf:{name:'PLENÁRIO DO STF',subtitle:'Três ondas nos corredores do poder.',boss:'GUARDIÃO DOS CORREDORES',length:1280,room:true},globonews:{name:'ESTÚDIO GLOBONEWS',subtitle:'A discussão saiu do controle.',boss:'O ÚLTIMO BLOCO',length:1280,room:true},urna:{name:'SEÇÃO ELEITORAL',subtitle:'Uma missão fictícia na sala de votação.',boss:'FIM DA FILA',length:1280,room:true},oval:{name:'CASA BRANCA',subtitle:'Trump observa, sentado à mesa ao fundo.',boss:'O ÚLTIMO CONVIDADO',length:1280,room:true}};
const enemyTypes={street:{name:'ARRUACEIRO',hp:38,speed:116,power:6,color:'#b97249'},runner:{name:'CORREDOR',hp:28,speed:170,power:5,color:'#65b9c8'},heavy:{name:'PESO PESADO',hp:64,speed:82,power:10,color:'#9e87c8'},boss:{name:'CHEFE',hp:210,speed:115,power:12,color:'#ed6a40'}};
function body(data,index,x,lane){return {data,index,x,lane,y:0,vy:0,vx:0,facing:1,hp:100,maxHp:100,meter:35,stun:0,cooldown:0,attackTime:0,attackKind:'',attackHit:false,hitIds:new Set(),block:false,shield:0,invincible:0,dead:false,combo:0,comboClock:0,lives:3,respawn:0,mass:68+data.power*7,motion:createMotion(index),injuries:[]}}
export class StreetRun{
 constructor(a,b,mode='solo',emit=()=>{},random=Math.random,arenaId=null,campSide='left',startStage=0,options={}){this.difficulty=options.difficulty||'standard';this.balance=difficulty(this.difficulty);this.campSide=campaignSides[campSide]?campSide:'left';this.arenaId=arenaId;this.arenaMission=arenaMissions[arenaId]||null;this.mode=mode;this.emit=emit;this.random=random;this.players=[body(a,0,240,500)];if(mode==='local')this.players.push(body(b,1,330,540));this.score=0;this.kills=0;this.stageIndex=this.arenaMission?0:clamp(Math.floor(Number(startStage)||0),0,stages.length-1);this.startStage=this.stageIndex;this.time=0;this.serial=0;this.loadStage()}
 get stage(){return this.arenaMission||stages[this.stageIndex]}
 get boss(){return bossFor(this.stage,this.campSide)}
 get livingEnemies(){return this.enemies.filter(e=>!e.dead)}
 get team(){return this.players.filter(p=>!p.dead)}
 get progress(){if(this.arenaMission)return clamp((this.wave-(this.waveActive?1:0))/3,0,1);return clamp((this.stageIndex+Math.max(...this.players.map(p=>p.x))/this.stage.length)/stages.length,0,1)}
 loadStage(){this.finisher=null;this.wave=0;this.waveActive=false;this.camera=0;this.gate=this.arenaMission?1210:1030;this.roomWait=0;this.enemies=[];this.projectiles=[];this.effects=[];this.pickups=[];this.target=null;this.dangers=[];this.state='intro';this.stateTime=2;this.notice='';this.noticeTime=0;this.objects=(this.arenaMission?[]:[700,1410,2270,2900]).map((x,i)=>({id:'o'+i,x,lane:i%2?550:454,hp:20,kind:i%2?'crate':'barrel',broken:false}));for(const p of this.players){p.x=240+p.index*90;p.lane=500+p.index*35;p.y=0;p.vy=0;p.dead=p.lives===0;p.hp=p.dead?0:Math.min(100,p.hp+25);p.stun=p.cooldown=p.attackTime=0;p.shield=0;p.dash=0;p.block=false;p.invincible=2;p.facing=1}this.emit('stage',{index:this.stageIndex});}
 nextStage(){if(this.state!=='stageclear')return false;if(this.stageIndex===stages.length-1){this.state='victory';return true}this.stageIndex++;this.loadStage();return true}
 announce(text){this.notice=text;this.noticeTime=2.6}
 spawnWave(){this.wave++;this.waveActive=true;const center=this.arenaMission?650:[620,1590,2680][this.wave-1];this.gate=this.arenaMission?1210:Math.min(this.stage.length-55,center+410);let types=this.wave===3?['street','runner','boss']:this.wave===2?['heavy','runner','street','street']:['street','street','runner'];if(this.mode==='local')types.push('heavy','runner');for(let i=0;i<types.length;i++){const type=types[i],stats=enemyTypes[type],scale=(1+this.stageIndex*.12)*this.balance.enemyHealth;const identity=type==='boss'?this.boss:null;const data={...stats,id:type,short:type==='boss'?this.stage.boss:stats.name,name:type==='boss'?this.stage.boss:stats.name,power:stats.power,guard:2,speed:3,symbol:'✦',type:'dash',...(identity||{})};const e=body(data,++this.serial,clamp(center+100+i*120,80,this.gate-40),435+(i%3)*55);e.enemy=true;e.enemyType=type;e.appearance=(e.index+this.stageIndex)%2?'light':'regional';e.neighborhoodId=this.arenaMission?null:this.stage.id;e.spriteColumn=type==='street'?(i%2?3:0):type==='runner'?1:2;e.bossIdentity=identity;e.specialClock=3;e.enraged=false;e.hp=e.maxHp=Math.round((identity?.master?320:stats.hp)*scale*(type==='boss'&&this.mode==='local'?1.5:1));e.facing=-1;e.aiClock=.7+i*.28;e.lives=1;this.enemies.push(e)}this.announce(this.wave===3?(this.boss?this.boss.name.toUpperCase()+' · '+(this.boss.master?'MASTER':this.stage.name):'CHEFE NA ÁREA'):'EMBOSCADA · GRUPO '+this.wave);this.emit('wave',{wave:this.wave})}
 attack(index,kind){if(kind==='fatal')return startStreetFinisher(this,index);if(this.finisher)return false;const p=this.players[index];if(!p||p.dead||this.state!=='fight'||p.stun>0||p.cooldown>0||p.block)return false;if(!['punch','kick','special','super'].includes(kind))return false;const cost=kind==='super'?100:kind==='special'?25:0;if(p.meter<cost){this.emit('dry',{index});return false}p.meter-=cost;p.attackKind=kind;p.attackTime=kind==='super'?.7:kind==='special'?.5:kind==='kick'?.4:.27;p.attackDuration=p.attackTime;p.cooldown=p.attackTime+.08;p.hitIds=new Set();p.attackHit=false;p.strikeIn=.065;this.emit('attack',{index,kind});
  if(kind==='special'||kind==='super'){p.invincible=Math.max(p.invincible,.55);if(kind==='super'){this.announce('BRASA MÁXIMA!');p.strikeIn=.16}else if(p.data.type==='projectile'){this.projectiles.push({owner:index,x:p.x+p.facing*55,lane:p.lane,y:p.y+100,vx:p.facing*580,radius:19,damage:23,life:1.9,color:p.data.color,symbol:p.data.symbol});p.strikeIn=-1}else if(p.data.type==='shield'){p.shield=3;p.strikeIn=-1}else if(p.data.type==='uppercut'&&p.y===0){p.vy=510;p.y=.1}else if(p.data.type==='dash')p.dash=.22}return true}
 strike(p){const kind=p.attackKind,range=kind==='super'?420:kind==='special'?185:kind==='kick'?145:110;for(const e of this.enemies){if(e.dead||p.hitIds.has(e.index)||Math.abs(p.lane-e.lane)>43||Math.abs(p.y-e.y)>155)continue;const dx=e.x-p.x;if(Math.abs(dx)<range&&(kind==='super'||kind==='special'||dx*p.facing>-20)){p.hitIds.add(e.index);const n=kind==='super'?70:kind==='special'?29:kind==='kick'?15:9;this.damageEnemy(e,n+p.data.power*.8,p,kind==='kick'||kind==='super')}}for(const o of this.objects){if(!o.broken&&Math.abs(o.x-p.x)<range&&Math.abs(o.lane-p.lane)<50&&(o.x-p.x)*p.facing>-20&&!p.hitIds.has(o.id)){p.hitIds.add(o.id);o.hp-=kind==='punch'?12:25;this.effects.push({x:o.x,lane:o.lane,y:45,life:.25,color:'#e4b773'});if(o.hp<=0){o.broken=true;this.score+=50;this.pickups.push({x:o.x,lane:o.lane,kind:o.kind==='barrel'?'food':'brasa',life:30});this.emit('break',{})}}}}
 damageEnemy(e,amount,p,knock=false){if(e.dead)return;if(e.shield>0)amount*=.4;e.hp=clamp(e.hp-amount,0,e.maxHp);e.stun=knock?.8:.36;e.vx=p.facing*(knock?330:145)*90/e.mass;addInjury(e,amount,this.random);e.motion.bodyV-=p.facing;e.attackTime=0;e.attackHit=true;e.cooldown=Math.max(e.cooldown,.65);p.combo++;p.comboClock=1.8;p.meter=clamp(p.meter+amount*.62,0,100);this.score+=Math.round(amount*8);this.target=e;this.effects.push({x:e.x,lane:e.lane,y:105,life:.23,color:'#ffe3a1'});this.emit('hit',{damage:amount,kind:p.attackKind});offerStreetFinisher(this,e);if(e.hp===0){e.dead=true;e.deathTime=.7;this.kills++;this.score+=e.enemyType==='boss'?1500:200;if(e.enemyType==='heavy')this.pickups.push({x:e.x,lane:e.lane,kind:'food',life:30})}}
 damagePlayer(p,amount,e){amount*=this.balance.enemyDamage;if(p.dead||p.invincible>0||this.state!=='fight')return false;const guard=p.block&&p.y===0&&p.facing*(e.x-p.x)>0;if(p.shield>0||guard){amount*=p.shield>0?.12:clamp(.48-p.data.guard*.045,.16,.5);this.emit('block',{})}else{p.stun=.38;p.vx=(p.x<e.x?-1:1)*210;p.attackTime=0;p.invincible=.65;addInjury(p,amount,this.random);p.motion.bodyV+=(p.x<e.x?-1:1)*1.2;p.motion.hairV-=amount*.06;this.emit('hurt',{index:p.index,damage:amount,kind:e.attackKind})}p.hp=clamp(p.hp-amount,0,100);p.meter=clamp(p.meter+amount,0,100);this.effects.push({x:p.x,lane:p.lane,y:100,life:.22,color:'#ff795e'});if(p.hp===0){p.lives--;p.dead=true;p.respawn=p.lives>0?2:0;this.emit('down',{index:p.index})}return true}
 update(dt,inputs=[{},{}]){dt=clamp(dt,0,.04);this.time+=dt;this.noticeTime=Math.max(0,this.noticeTime-dt);this.effects.forEach(e=>e.life-=dt);this.effects=this.effects.filter(e=>e.life>0);if(stepStreetFinisher(this,dt))return;if(this.state==='intro'){this.stateTime-=dt;if(this.stateTime<=0){this.state='fight';this.spawnWave()}return}if(this.state!=='fight'){if(['stageclear','victory','gameover'].includes(this.state)){for(const f of [...this.players,...this.enemies]){f.vx=approach(f.vx,0,17,dt);this.tickBody(f,dt);if(f.enemy&&f.dead)f.deathTime=Math.max(0,(f.deathTime||0)-dt)}}return;}
  for(const p of this.players){if(p.dead){this.tickBody(p,dt);if(p.respawn>0){p.respawn-=dt;if(p.respawn<=0){p.dead=false;p.hp=100;p.x=clamp(this.camera+250,70,this.gate-50);p.invincible=3;p.y=0;p.vy=0;p.stun=p.cooldown=p.attackTime=0}}continue}const input=inputs[p.index]||{};this.tickBody(p,dt);p.block=!!input.block&&!p.stun&&!p.attackTime&&p.y===0;const dx=(input.right?1:0)-(input.left?1:0),dy=(input.down?1:0)-(input.up?1:0),norm=dx&&dy?Math.SQRT1_2:1;const speed=170+p.data.speed*19;if(!p.stun&&!p.block){if(p.dash>0){p.dash-=dt;p.vx=p.facing*850}else p.vx=approach(p.vx,p.attackTime?0:dx*speed*norm,p.y>0?4:14,dt);if(dx&&!p.attackTime)p.facing=dx;if(!p.attackTime)p.lane=clamp(p.lane+dy*speed*.62*dt*norm,422,565);if(input.jump&&p.y===0&&!p.attackTime){p.vy=555;p.y=.1}}p.x=clamp(p.x+p.vx*dt,this.camera+55,this.gate);if(p.attackTime>0){p.strikeIn-=dt;if(p.strikeIn<=0&&p.strikeIn>-.5){this.strike(p);p.strikeIn=-1}}}
  if(!this.team.length&&this.players.every(p=>!p.respawn)){this.state='gameover';this.emit('gameover',{});return}
  for(const e of this.enemies){if(e.dead){this.tickBody(e,dt);e.deathTime=Math.max(0,(e.deathTime||0)-dt);continue}this.tickBody(e,dt);const candidates=this.team;if(!candidates.length)continue;const p=candidates.reduce((a,b)=>Math.abs(a.x-e.x)+Math.abs(a.lane-e.lane)<Math.abs(b.x-e.x)+Math.abs(b.lane-e.lane)?a:b);if(e.bossIdentity&&e.hp<e.maxHp*.5&&!e.enraged){e.enraged=true;this.announce(e.data.name.toUpperCase()+' · SEGUNDO FÔLEGO');e.specialClock=.8}e.specialClock-=dt;if(e.stun>0){e.x=clamp(e.x+e.vx*dt,this.camera+40,this.gate+100);continue}if(e.bossIdentity&&e.specialClock<=0&&e.cooldown===0&&Math.abs(e.x-p.x)<650){this.bossSpecial(e,p);continue}if(e.attackTime>0){e.strikeIn-=dt;if(e.strikeIn<=0&&!e.attackHit){e.attackHit=true;if(Math.abs(e.x-p.x)<110&&Math.abs(e.lane-p.lane)<37&&p.y<85)this.damagePlayer(p,enemyTypes[e.enemyType].power+this.stageIndex*.5,e)}continue}e.facing=p.x>=e.x?1:-1;e.aiClock-=dt;const dx=p.x-e.x,dy=p.lane-e.lane;if(Math.abs(dx)>78)e.x+=Math.sign(dx)*enemyTypes[e.enemyType].speed*this.balance.enemySpeed*(e.enraged?1.12:1)*dt;if(Math.abs(dy)>8)e.lane+=Math.sign(dy)*enemyTypes[e.enemyType].speed*.55*dt;e.vx=Math.abs(dx)>78?Math.sign(dx)*90:0;if(Math.abs(dx)<112&&Math.abs(dy)<32&&e.cooldown===0&&e.aiClock<=0&&this.enemies.filter(a=>!a.dead&&a.attackTime>0).length<this.balance.attackers){e.attackTime=e.enemyType==='boss'?.85:.68;e.attackKind='punch';e.attackDuration=e.attackTime;e.strikeIn=e.enemyType==='boss'?.64:.48;e.attackHit=false;e.cooldown=(1.6+this.random()*.6)*this.balance.cadence;e.aiClock=.3}e.x=clamp(e.x,this.camera+35,this.gate+120)}
  // Separate attackers slightly, while preserving their ground-plane hit tests.
  const alive=this.livingEnemies;for(let i=0;i<alive.length;i++)for(let j=i+1;j<alive.length;j++){const a=alive[i],b=alive[j];if(Math.abs(a.x-b.x)<38&&Math.abs(a.lane-b.lane)<26){const sign=a.lane<=b.lane?1:-1;a.lane=clamp(a.lane-sign*18*dt,422,565);b.lane=clamp(b.lane+sign*18*dt,422,565)}}
  for(const d of this.dangers){if(d.enemy.dead)continue;d.delay-=dt;if(d.delay<=0){for(const p of this.team)if(Math.abs(p.x-d.x)<d.radius&&Math.abs(p.lane-d.lane)<40&&p.y<90)this.damagePlayer(p,d.damage,d.enemy);this.effects.push({x:d.x,lane:d.lane,y:50,life:.35,color:d.color})}}this.dangers=this.dangers.filter(d=>d.delay>0&&!d.enemy.dead);for(const q of this.projectiles){q.x+=q.vx*dt;q.life-=dt;for(const e of q.enemy?this.team:alive){if(q.life>0&&Math.abs(q.x-e.x)<43&&Math.abs(q.lane-e.lane)<38&&(!q.enemy||e.y<85)){if(q.enemy)this.damagePlayer(e,q.damage,q.enemy);else this.damageEnemy(e,q.damage,this.players[q.owner]);q.life=0}}}this.projectiles=this.projectiles.filter(q=>q.life>0);
  for(const item of this.pickups){item.life-=dt;for(const p of this.team){if(item.life>0&&Math.abs(item.x-p.x)<42&&Math.abs(item.lane-p.lane)<30){if(item.kind==='food')p.hp=clamp(p.hp+35,0,100);else p.meter=clamp(p.meter+35,0,100);item.life=0;this.score+=100;this.emit('pickup',{kind:item.kind})}}}this.pickups=this.pickups.filter(p=>p.life>0);
  if(this.waveActive&&!this.livingEnemies.length){this.roomWait=.8;this.waveActive=false;this.gate=this.wave===3?this.stage.length-55:[1590,2680][this.wave-1]+410;this.announce('CAMINHO LIVRE · AVANCE →');this.emit('clear',{})}
  if(this.arenaMission){this.camera=0;if(!this.waveActive){this.gate=1210;this.roomWait-=dt;if(this.wave===3){this.state='victory';this.score+=2000;this.emit('stageclear',{})}else if(this.roomWait<=0)this.spawnWave()}return}
  const lead=Math.max(...this.team.map(p=>p.x),this.camera+240);if(!this.waveActive&&this.wave<3&&lead>=[620,1590,2680][this.wave]-450)this.spawnWave();const rear=Math.min(...this.team.map(p=>p.x),lead);this.camera=clamp(Math.min(lead-440,rear-140),this.camera,this.stage.length-1280);if(this.wave===3&&!this.waveActive&&lead>=this.stage.length-200){this.state=this.stageIndex===stages.length-1?'victory':'stageclear';this.score+=2000;this.emit('stageclear',{})}
 }
 bossSpecial(e,p){const kind=e.data.type;e.specialClock=e.enraged?3.7:5.1;e.cooldown=1.3;e.attackKind='special';e.attackTime=.85;e.attackDuration=.85;e.attackHit=true;e.facing=p.x>=e.x?1:-1;this.emit('boss-special',{name:e.data.name,kind});if(kind==='shield'){e.shield=2.3;this.announce(e.data.name.toUpperCase()+' · GUARDA REFORÇADA')}else if(kind==='projectile'){this.projectiles.push({enemy:e,x:e.x+e.facing*60,lane:e.lane,y:100,vx:e.facing*320,radius:22,damage:e.bossIdentity.master?16:11,life:3,color:e.data.color,symbol:e.data.symbol})}else{this.dangers.push({enemy:e,x:p.x,lane:p.lane,radius:kind==='area'?120:88,delay:kind==='dash'?.8:.95,damage:e.bossIdentity.master?19:14,color:e.data.color});if(kind==='dash'){e.x=clamp(p.x-e.facing*115,this.camera+45,this.gate);e.lane=p.lane}else if(kind==='uppercut'){e.vy=430;e.y=.1}}}
 tickBody(f,dt){f.finishWindow=Math.max(0,(f.finishWindow||0)-dt);stepMotion(f,dt,this.state);const foot=Math.floor(f.motion.gait/Math.PI);if(!f.dead&&!f.enemy&&f.motion.walk>.4&&foot!==f.lastFoot){f.lastFoot=foot;this.emit('step',{index:f.index})}for(const key of ['stun','cooldown','attackTime','shield','invincible'])f[key]=Math.max(0,f[key]-dt);f.comboClock-=dt;if(f.comboClock<=0)f.combo=0;stepVertical(f,dt,1450,speed=>this.emit('land',{index:f.index,speed}));}
}
